<script setup lang="ts">
import {transactionSummary} from './summary'
import {useI18n} from 'vue-i18n'
import {money,dateTime} from '../format'
import {transactionDetailTarget} from './query'
import type {Transaction} from './types'
const props=defineProps<{row:Transaction;customer:boolean;returnTo:string}>(),{t}=useI18n()
</script>
<template><RouterLink class="wallet-card wallet-transaction-row" :to="transactionDetailTarget(row,customer,returnTo)"><div><strong>{{t(`wallet.transactions.${row.type}`)}}</strong><span><small class="wallet-flow-badge">{{t(`wallet.transactions.flow_${row.direction}`)}}</small>{{t(`wallet.transactions.${row.status}`)}}</span></div><strong v-if="row.sourceType==='points'">{{row.direction==='in'?'+':row.direction==='out'?'−':''}}{{row.quantity}} {{t('wallet.transactions.points')}}</strong><strong v-else>{{money(row.amountCents)}} {{row.currency}}</strong><p v-if="row.status!=='completed'" class="wallet-muted">{{t(row.type==='refund'&&row.status==='pending'?'wallet.transactions.refundPending':'wallet.transactions.notPosted')}}</p><p v-if="row.sourceType!=='points'&&(row.status==='completed'||row.type==='refund')"><template v-if="row.type!=='reversal'&&row.status==='completed'">{{t(row.type==='refund'?(customer?'wallet.transactions.cashRefundIn':'wallet.transactions.cashRefundOut'):(customer?'wallet.transactions.customerOut':'wallet.transactions.moneyIn'))}} {{money(row.type==='refund'?row.externalPaidCents:row.type==='topup'?row.principalCents:row.walletPaidCents+row.externalPaidCents)}} · </template>{{t('wallet.transactions.walletDelta')}} {{row.walletDeltaCents>0?'+':''}}{{money(row.walletDeltaCents)}}</p><p v-if="row.type==='topup'">{{t(row.status==='completed'?(customer?'wallet.transactions.customerTopup':'wallet.transactions.topupPrincipalCents'):'wallet.transactions.plannedPrincipal')}} {{money(row.principalCents)}} · {{t('wallet.transactions.topupBonusCents')}} {{money(row.bonusCents)}} · {{t('wallet.transactions.topupCreditCents')}} {{money(row.creditTotalCents)}}</p><p v-if="row.type==='payment'">{{t('wallet.transactions.walletPaymentCents')}} {{money(row.walletPaidCents)}} · {{t(customer?'wallet.transactions.customerExternal':'wallet.transactions.externalPaymentCents')}} {{money(row.externalPaidCents)}} <span v-if="row.refundStatus&&row.refundStatus!=='none'"> · {{t('wallet.transactions.refundStatus')}} {{t(`wallet.states.${row.refundStatus}`)}}</span></p><p v-if="transactionSummary(row,t)">{{transactionSummary(row,t)}}</p><small v-if="!customer&&row.actorName">{{t('wallet.transactions.actor')}}: {{row.actorName}}</small><p>{{row.storeName}}<template v-if="row.customerName"> · {{row.customerName}} {{row.customerPhone}}</template></p><small>{{dateTime(row.occurredAt,row.timeZone)}} · {{row.id}}</small></RouterLink></template>
